+TEST(DynamicWindowPurePursuitTest, computeDynamicWindow)
+{
+  double max_linear_vel = 0.5;
+  double min_linear_vel = -0.5;
+  double max_angular_vel = 1.0;
+  double min_angular_vel = -1.0;
+  double max_linear_accel = 0.5;
+  double max_linear_decel = -1.0;
+  double max_angular_accel = 1.0;
+  double max_angular_decel = -2.0;
+  double control_duration = 1.0 / 20.0;
+
+  DynamicWindowBounds dynamic_window;
+  geometry_msgs::msg::Twist current_speed = geometry_msgs::msg::Twist();
+
+  // case1: current linear velocity is positive, angular velocity is positive,
+  // clip by max linear vel
+  current_speed.linear.x = 0.5; current_speed.angular.z = 0.2;
+
+  dynamic_window = computeDynamicWindow(
+    current_speed, max_linear_vel, min_linear_vel,
+    max_angular_vel, min_angular_vel,
+    max_linear_accel, max_linear_decel,
+    max_angular_accel, max_angular_decel, control_duration);
+
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.5);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.45);
+  EXPECT_EQ(dynamic_window.max_angular_vel, 0.25);
+  EXPECT_EQ(dynamic_window.min_angular_vel, 0.10);
+
+  // case2: current linear velocity is positive, angular velocity is negative
+  current_speed.linear.x = 0.3; current_speed.angular.z = -0.2;
+
+  dynamic_window = computeDynamicWindow(
+    current_speed, max_linear_vel, min_linear_vel,
+    max_angular_vel, min_angular_vel,
+    max_linear_accel, max_linear_decel,
+    max_angular_accel, max_angular_decel, control_duration);
+
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.325);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.25);
+  EXPECT_EQ(dynamic_window.max_angular_vel, -0.1);
+  EXPECT_EQ(dynamic_window.min_angular_vel, -0.25);
+
+  // case3: current linear velocity is zero, angular velocity is zero
+  current_speed.linear.x = 0.0; current_speed.angular.z = -0.0;
+
+  dynamic_window = computeDynamicWindow(
+    current_speed, max_linear_vel, min_linear_vel,
+    max_angular_vel, min_angular_vel,
+    max_linear_accel, max_linear_decel,
+    max_angular_accel, max_angular_decel, control_duration);
+
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.025);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.025);
+  EXPECT_EQ(dynamic_window.max_angular_vel, 0.05);
+  EXPECT_EQ(dynamic_window.min_angular_vel, -0.05);
+
+  // case4: current linear velocity is negative, angular velocity is positive
+  current_speed.linear.x = -0.3; current_speed.angular.z = 0.2;
+
+  dynamic_window = computeDynamicWindow(
+    current_speed, max_linear_vel, min_linear_vel,
+    max_angular_vel, min_angular_vel,
+    max_linear_accel, max_linear_decel,
+    max_angular_accel, max_angular_decel, control_duration);
+
+  EXPECT_EQ(dynamic_window.max_linear_vel, -0.25);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.325);
+  EXPECT_EQ(dynamic_window.max_angular_vel, 0.25);
+  EXPECT_EQ(dynamic_window.min_angular_vel, 0.10);
+
+  // case5: current linear velocity is negative, angular velocity is negative,
+  // clipped by min lenear vel
+  current_speed.linear.x = -0.5; current_speed.angular.z = -0.2;
+
+  dynamic_window = computeDynamicWindow(
+    current_speed, max_linear_vel, min_linear_vel,
+    max_angular_vel, min_angular_vel,
+    max_linear_accel, max_linear_decel,
+    max_angular_accel, max_angular_decel, control_duration);
+
+  EXPECT_EQ(dynamic_window.max_linear_vel, -0.45);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.5);
+  EXPECT_EQ(dynamic_window.max_angular_vel, -0.1);
+  EXPECT_EQ(dynamic_window.min_angular_vel, -0.25);
+}
+
+TEST(DynamicWindowPurePursuitTest, applyRegulationToDynamicWindow)
+{
+  double regulated_linear_vel;
+  DynamicWindowBounds dynamic_window;
+
+  regulated_linear_vel = 0.3;
+
+  dynamic_window.max_linear_vel = 0.5;
+  dynamic_window.min_linear_vel = 0.4;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.4);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.4);
+
+  dynamic_window.max_linear_vel = 0.4;
+  dynamic_window.min_linear_vel = 0.2;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.3);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.2);
+
+  dynamic_window.max_linear_vel = 0.2;
+  dynamic_window.min_linear_vel = 0.1;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.2);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.1);
+
+  dynamic_window.max_linear_vel = 0.1;
+  dynamic_window.min_linear_vel = -0.2;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.1);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.0);
+
+  dynamic_window.max_linear_vel = -0.1;
+  dynamic_window.min_linear_vel = -0.3;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, -0.1);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.1);
+
+  regulated_linear_vel = -0.3;
+
+  dynamic_window.max_linear_vel = 0.3;
+  dynamic_window.min_linear_vel = 0.1;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.1);
+  EXPECT_EQ(dynamic_window.min_linear_vel, 0.1);
+
+  dynamic_window.max_linear_vel = 0.1;
+  dynamic_window.min_linear_vel = -0.2;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, 0.0);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.2);
+
+  dynamic_window.max_linear_vel = -0.2;
+  dynamic_window.min_linear_vel = -0.3;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, -0.2);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.3);
+
+  dynamic_window.max_linear_vel = -0.2;
+  dynamic_window.min_linear_vel = -0.4;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, -0.2);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.3);
+
+  dynamic_window.max_linear_vel = -0.4;
+  dynamic_window.min_linear_vel = -0.5;
+  applyRegulationToDynamicWindow(
+    regulated_linear_vel,
+    dynamic_window);
+  EXPECT_EQ(dynamic_window.max_linear_vel, -0.4);
+  EXPECT_EQ(dynamic_window.min_linear_vel, -0.4);
+}
