+    tf.child_frame_id = "base_link";
+    tf.transform.translation.x = x;
+    tf.transform.translation.y = y;
+    tf.transform.translation.z = 0.0;
+    tf.transform.rotation.w = 1.0;
+
+    tf_buffer_->setTransform(tf, "unit_test", true);
+  }
