+  update();
+
+  unsigned int mx, my;
+  obstacle_layer_->worldToMap(0.5, 0.0, mx, my);
+  unsigned char cost = obstacle_layer_->getCost(mx, my);
+
+  ASSERT_EQ(cost, nav2_costmap_2d::LETHAL_OBSTACLE);
+}
+
+/**
