+/// @brief create mapping '.'->0, 'a'->1, 'b'->2, ... max_symbol->n
+std::map<char, uint8_t> makeLabelsMap(char max_symbol)
+{
+  std::map<char, uint8_t> labels_map = {{'.', 0}};
+
+  for (char s = 'a'; s <= max_symbol; ++s) {
+    labels_map.emplace(s, uint8_t(s - 'a' + 1));
+  }
+  return labels_map;
+}
