+    pose.pose.orientation.z = 0.0;
+    pose.pose.orientation.w = 1.0;
+    for (int i = 0; i < 6; ++i) {
+      result_->path.poses.push_back(pose);
+    }
+  }
+
+  std::shared_ptr<nav2_msgs::action::ComputePathToPose::Result> fillResult() override
+  {
+    return result_;
+  }
