+      };
+
+    factory_->registerBuilder<nav2_behavior_tree::SmoothPathAction>(
+      "SmoothPath", builder);
+  }
+
+  static void TearDownTestCase()
+  {
+    delete config_;
+    config_ = nullptr;
+    node_.reset();
+    action_server_.reset();
+    factory_.reset();
