+  }
+
+  bool ulosCheck(const int & x0, const int & y0, const int & x1, const int & y1, double & sl_cost)
+  {
+    return losCheck(x0, y0, x1, y1, sl_cost);
+  }
+
+  bool uwithinLimits(const int & cx, const int & cy) {return withinLimits(cx, cy);}
