+
+// Return a zero matrix
+pf_matrix_t pf_matrix_zero()
+{
+  int i, j;
+  pf_matrix_t c;
+
+  for (i = 0; i < 3; i++)
+    for (j = 0; j < 3; j++)
+      c.m[i][j] = 0.0;
+        
+  return c;
+}
+
+
+// Check for NAN or INF in any component
+int pf_matrix_finite(pf_matrix_t a)
+{
+  int i, j;
+  
+  for (i = 0; i < 3; i++)
+    for (j = 0; j < 3; j++)
+      if (!finite(a.m[i][j]))
+        return 0;
+  
+  return 1;
+}
+
+
+// Print a matrix
+void pf_matrix_fprintf(pf_matrix_t a, FILE *file, const char *fmt)
+{
+  int i, j;
+
+  for (i = 0; i < 3; i++)
+  {
+    for (j = 0; j < 3; j++)
+    {
+      fprintf(file, fmt, a.m[i][j]);
+      fprintf(file, " ");
+    }
+    fprintf(file, "\n");
+  }
+  return;     
+}
