+////////////////////////////////////////////////////////////////////////////////
+// Default constructor
+AMCLLaser::AMCLLaser(size_t max_beams, map_t* map) : AMCLSensor(), 
+						     max_samples(0), max_obs(0), 
+						     temp_obs(NULL)
+{
+  this->time = 0.0;
+
+  this->max_beams = max_beams;
+  this->map = map;
+
+  return;
+}
+
+AMCLLaser::~AMCLLaser()
+{
+  if(temp_obs){
+	for(int k=0; k < max_samples; k++){
+	  delete [] temp_obs[k];
+	}
+	delete []temp_obs; 
+  }
+}
