+// just initialize everything to NULL by default
+Costmap2D::Costmap2D() :
+    size_x_(0), size_y_(0), resolution_(0.0), origin_x_(0.0), origin_y_(0.0), costmap_(NULL)
+{
+  access_ = new mutex_t();
+}
