+  vvf = parseVVF( "[[1, 2.2], [.3, -4e4]]", error );
+  EXPECT_EQ( 2, vvf.size() );
+  EXPECT_EQ( 2, vvf[0].size() );
+  EXPECT_EQ( 2, vvf[1].size() );
+  EXPECT_EQ( 1.0f, vvf[0][0] );
+  EXPECT_EQ( 2.2f, vvf[0][1] );
+  EXPECT_EQ( 0.3f, vvf[1][0] );
+  EXPECT_EQ( -40000.0f, vvf[1][1] );
